using System.IO;
using System.Windows.Media.Imaging;
using SnipToss.App;

namespace AppTests;

/// <summary>
/// The program icon (app/SnipToss.ico, generated by scripts/build-icon.mjs): the sizes Windows picks from at 100% to 200% scaling
/// (title bar, taskbar, Alt+Tab, tray, Explorer), and the copy compiled into the program is the one in the source tree
/// </summary>
public class IconTests
{
    static readonly int[] Sizes = [16, 20, 24, 32, 40, 48, 64, 256];

    static string RepoFile(params string[] parts)
    {
        for (var d = new DirectoryInfo(AppContext.BaseDirectory); d is not null; d = d.Parent)
        {
            var file = Path.Combine([d.FullName, .. parts]);
            if (File.Exists(file)) return file;
        }
        throw new InvalidOperationException($"{string.Join('/', parts)} not found");
    }

    [Fact]
    public void Icon_file_has_the_eight_sizes_and_every_frame_decodes_at_its_size()
    {
        var bytes = File.ReadAllBytes(RepoFile("app", "SnipToss.ico"));
        // ICONDIR: reserved 0, type 1 (icon), the number of images
        Assert.Equal((0, 1, Sizes.Length), (BitConverter.ToUInt16(bytes, 0), BitConverter.ToUInt16(bytes, 2), (int)BitConverter.ToUInt16(bytes, 4)));

        var listed = new List<int>();
        for (var i = 0; i < Sizes.Length; i++)
        {
            var at = 6 + 16 * i;
            // ICONDIRENTRY: width and height (256 is stored as 0), planes, bits per pixel, data size, data offset
            int width = bytes[at] == 0 ? 256 : bytes[at];
            int height = bytes[at + 1] == 0 ? 256 : bytes[at + 1];
            Assert.Equal(width, height);
            Assert.Equal(32, BitConverter.ToUInt16(bytes, at + 6));
            var size = (int)BitConverter.ToUInt32(bytes, at + 8);
            var offset = (int)BitConverter.ToUInt32(bytes, at + 12);
            Assert.True(offset + size <= bytes.Length, $"The {width}px frame runs past the end of the file");
            listed.Add(width);

            // Each frame is a PNG of exactly the size the directory says
            Assert.Equal(new byte[] { 0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A }, bytes[offset..(offset + 8)]);
            var frame = new PngBitmapDecoder(new MemoryStream(bytes, offset, size), BitmapCreateOptions.None, BitmapCacheOption.OnLoad).Frames.Single();
            Assert.Equal((width, width), (frame.PixelWidth, frame.PixelHeight));
        }
        Assert.Equal(Sizes, listed.Order());

        // And the system's own icon decoder agrees: it finds the same eight frames
        var all = new IconBitmapDecoder(new MemoryStream(bytes), BitmapCreateOptions.None, BitmapCacheOption.OnLoad).Frames;
        Assert.Equal(Sizes, all.Select(f => f.PixelWidth).Order());
    }

    [Fact]
    public void Icon_compiled_into_the_program_is_byte_for_byte_the_one_in_the_source_tree()
    {
        // The tray icon reads pack://application:,,,/SnipToss.ico (Tray.cs): the WPF resource baked into the assembly. If the icon is regenerated
        // and the program is not rebuilt, the tray would still show the old one
        var assembly = typeof(Tray).Assembly;
        using var resources = new System.Resources.ResourceReader(assembly.GetManifestResourceStream($"{assembly.GetName().Name}.g.resources")!);
        byte[]? embedded = null;
        foreach (System.Collections.DictionaryEntry entry in resources)
        {
            if (string.Equals((string)entry.Key, "sniptoss.ico", StringComparison.OrdinalIgnoreCase))
            {
                using var stream = (Stream)entry.Value!;
                using var copy = new MemoryStream();
                stream.CopyTo(copy);
                embedded = copy.ToArray();
            }
        }
        Assert.NotNull(embedded);
        Assert.Equal(File.ReadAllBytes(RepoFile("app", "SnipToss.ico")), embedded);
    }
}
